('f0a4a670-850f-11f1-ba38-28d0eaec4da6', 'ভাইব্রান্ট টিল ডটেড স্লিম ফিট শার্ট', 'vibrant-teal-dotted-slim-fit-shirt', 'সূক্ষ্ম ডট প্যাটার্ন সহ স্টাইলিশ টিল শার্ট। আধুনিক এবং পরিশীলিত চেহারার জন্য স্লিম ফিট ডিজাইন।', NULL, 1290.00, NULL, NULL, NULL, 38, '6b143829-dc22-4eaa-948b-00d202b700d0', NULL, 'http://127.0.0.1:8000/storage/uploads/product-images/Vu4FiO1Utewu69SoodeJqJTtzk8VaSe5gy0bUCVN.webp', '[]', 1, 0, NULL, NULL, '2026-07-21 08:24:53', '2026-07-26 01:18:36', 'Vibrant Teal Dotted Slim Fit Shirt', 'ভাইব্রান্ট টিল ডটেড স্লিম ফিট শার্ট', NULL, NULL, 'Stylish teal shirt with subtle dot pattern. Slim fit design for a modern and sophisticated look.', 'সূক্ষ্ম ডট প্যাটার্ন সহ স্টাইলিশ টিল শার্ট। আধুনিক এবং পরিশীলিত চেহারার জন্য স্লিম ফিট ডিজাইন।', NULL, NULL, NULL, NULL);
INSERT INTO `reviews` (`id`, `product_id`, `customer_name`, `avatar_url`, `rating`, `review_text`, `is_approved`, `is_featured`, `sort_order`, `created_at`, `updated_at`) VALUES
('411ea407-6f6d-414d-8cc3-e002d25cf086', NULL, 'রহিমা আক্তার', 'https://i.pravatar.cc/150?img=47', 5, 'ক্লাসিক ব্রাউন মনোগ্রাম হ্যান্ডব্যাগটা ছবিতে যেমন দেখেছি, হাতে পেয়ে ঠিক তেমনই। ফিনিশিং আর প্যাকেজিং দুটোই দারুণ। ধন্যবাদ ড্রিম মার্ট!', 1, 1, 1, '2026-07-21 08:24:51', '2026-07-21 08:24:51'),
('4579094d-5a37-49d7-86c0-13a12b8dcbbf', NULL, 'সাবিনা ইয়াসমিন', 'https://i.pravatar.cc/150?img=44', 4, 'বেবি গার্ল ফ্রক আর কার্টুন প্রিন্ট বেবি স্যান্ডেল দুটোই ফ্রেশ পেয়েছি। বাচ্চারা খুব পছন্দ করেছে। ধন্যবাদ ড্রিম মার্ট!', 1, 1, 6, '2026-07-21 08:24:51', '2026-07-21 08:24:51'),
('553e2661-05db-4df3-a9fe-cdaa45d6f9f4', NULL, 'করিম উদ্দিন', 'https://i.pravatar.cc/150?img=57', 5, 'প্রিমিয়াম কটন লুঙ্গির কাপড় খুবই আরামদায়ক, রঙও নষ্ট হয়নি। নিয়মিত ব্যবহার করছি, আবার অর্ডার করবো ইনশাআল্লাহ।', 1, 1, 5, '2026-07-21 08:24:51', '2026-07-21 08:24:51'),
('8529c0fa-8595-4749-b320-a4768d8300f0', NULL, 'তানভীর হাসান', 'https://i.pravatar.cc/150?img=15', 5, 'ওয়্যারলেস ব্লুটুথ ইয়ারবাডস ২৪ ঘন্টার মধ্যে ডেলিভারি পেয়েছি। সাউন্ড কোয়ালিটি আর ব্যাটারি ব্যাকআপ দুটোই দারুণ। ড্রিম মার্ট-কে ধন্যবাদ।', 1, 1, 3, '2026-07-21 08:24:51', '2026-07-21 08:24:51'),
('93417ca3-bce2-4ecf-b54d-0be57273bab0', NULL, 'আব্দুল মালেক', 'https://i.pravatar.cc/150?img=12', 5, 'গোল্ডেন স্কেলিটন ডায়াল ঘড়িটা একদম অরিজিনাল, দাম অনুযায়ী কোয়ালিটি অসাধারণ। সবাই জিজ্ঞেস করে কোথা থেকে নিলাম।', 1, 1, 2, '2026-07-21 08:24:51', '2026-07-21 08:24:51'),
('9b14766c-1da6-4051-bb2f-9197dbedef9a', NULL, 'ফাতেমা বেগম', 'https://i.pravatar.cc/150?img=49', 5, 'অনেক দিন ধরে ভালো কটন এমব্রয়ডারি সালোয়ার কামিজ খুঁজছিলাম, অবশেষে ড্রিম মার্ট-এ পেলাম! কাপড় আর সেলাইয়ের কাজ একদম নিখুঁত।', 1, 1, 4, '2026-07-21 08:24:51', '2026-07-21 08:24:51'),
('a25c7976-e98d-446f-b268-230a8d43a691', NULL, 'নাসরিন সুলতানা', 'https://i.pravatar.cc/150?img=45', 5, 'রোজ ভেলভেট পারফিউমের ঘ্রাণ অনেকক্ষণ থাকে, একদম অরিজিনাল প্রোডাক্ট। বারবার কিনব ড্রিম মার্ট থেকে।', 1, 1, 8, '2026-07-21 08:24:51', '2026-07-21 08:24:51'),
('eedcdc43-1108-425e-9c2e-ecf8bf50e828', NULL, 'মোঃ রাসেল মিয়া', 'https://i.pravatar.cc/150?img=59', 5, '১০০০০ এমএএইচ পাওয়ার ব্যাংক আর স্মার্ট ওয়াচ দুটোই সম্পূর্ণ অরিজিনাল, কোনো ঝামেলা নেই। পরিবারের সবাই পছন্দ করেছে।', 1, 1, 7, '2026-07-21 08:24:51', '2026-07-21 08:24:51');
